export interface ClipRunConfig {
  limit?: number;         // max briefs to process (default: 5)
  status_filter?: string; // 'approved' (default) | 'draft' (for testing)
  start_seconds?: number; // clip start offset in source video (default: 10)
  clips_dir?: string;     // output directory (default: ~/kognai/clips)
  dry_run?: boolean;      // download + extract but don't update DB
}

export interface ClipRunResult {
  processed: number;
  clips_made: number;
  clips_stored: number;
  errors: string[];
  duration_ms: number;
}

export async function runClipMaker(config: ClipRunConfig): Promise<ClipRunResult>;
```

Pipeline:
1. Query tiktok_briefs WHERE status = config.status_filter (default: 'approved') AND clip_status = 'pending' ORDER BY score DESC LIMIT limit
2. Ensure clips_dir exists (mkdir -p)
3. For each brief:
   a. downloadVideo(brief.ia_identifier, downloads_dir) — temp storage at ~/kognai/downloads/
   b. const outputPath = path.join(clips_dir, `{brief.id}.mp4`)
   c. extractClip(videoPath, outputPath, { startSeconds, durationSeconds: brief.duration_seconds })
   d. If !dry_run: UPDATE tiktok_briefs SET clip_path={outputPath}, clip_status='ready' WHERE id={brief.id}
   e. Log: `[clip-maker] [T03] "Soviet scientists..." → clips/abc123.mp4 (28s)`
4. Return ClipRunResult

Entry point:
```typescript
if (import.meta.url === `file://${process.argv[1]}`) {
  const isDryRun = process.argv.includes('--dry-run');
  const isDraft = process.argv.includes('--draft');  // use draft briefs for testing
  runClipMaker({
    limit: 5,
    status_filter: isDraft ? 'draft' : 'approved',
    dry_run: isDryRun,
  }).then(r => {
    console.log(`\n=== DONE: ${r.clips_made} clips made, ${r.clips_stored} stored ===`);
    if (r.errors.length) console.log('Errors:', r.errors);
  });
}
